-- LESSON 1 ASSIGNMENT 1 Find the title of each film (SELECT TITLE FROM movies;)
-- LESSON 1 ASSIGNMENT 2 Find the director of each film (SELECT DIRECTOR FROM movies;)
-- LESSON 1 ASSIGNMENT 3 Find the title and director of each film (SELECT TITLE, DIRECTOR FROM movies;)
-- LESSON 1 ASSIGNMENT 4 Find the title and year of each film (SELECT TITLE, YEAR FROM movies;)
-- LESSON 1 ASSIGNMENT 5 Find all the information about each film (SELECT * FROM movies;)
-- LESSON 2 ASSIGNMENT 1 Find the movie with a row id of 6 (SELECT * FROM movies WHERE ID=6;)
-- LESSON 2 ASSIGNMENT 2 Find the movies released in the years between 2000 and 2010 (SELECT * FROM movies WHERE YEAR BETWEEN 2000 AND 2010;)
-- LESSON 2 ASSIGNMENT 3 Find the movies not released in the years between 2000 and 2010 (SELECT * FROM movies WHERE YEAR NOT BETWEEN 2000 AND 2010;)
-- LESSON 2 ASSIGNMENT 4 Find the first 5 Pixar movies and their release year (SELECT * FROM movies WHERE Id <= 5 ;)
-- LESSON 3 ASSIGNMENT 1 Find all the Toy Story movies (SELECT * FROM movies WHERE Title LIKE "%Toy Story%";)
-- LESSON 3 ASSIGNMENT 2 Find all the movies directed by John Lasseter (SELECT Title FROM movies WHERE Director = "John Lasseter";)
-- LESSON 3 ASSIGNMENT 3 Find all the movies (and director) not directed by John Lasseter (SELECT Title,Director FROM movies WHERE Director != "John Lasseter";)
-- LESSON 3 ASSIGNMENT 4 Find all the WALL-* movies (SELECT Title FROM movies WHERE Title LIKE "%WALL-_";)
